// If startLine > 0, only considers lines from startLine onwards.
func CalculateTokenUsageFromFile(path string, startLine int) (*TokenUsage, error) {
	if path == "" {
		return &TokenUsage{}, nil
	}

	transcript, _, err := parseTranscriptFromLine(path, startLine)
	if err != nil {
		return nil, err
	}

	return CalculateTokenUsage(transcript), nil
}

