// accumulateTokenUsage adds new token usage to existing accumulated usage.
// If existing is nil, returns a copy of new. If new is nil, returns existing unchanged.
func accumulateTokenUsage(existing, new *checkpoint.TokenUsage) *checkpoint.TokenUsage {
	if new == nil {
		return existing
	}
	if existing == nil {
		// Return a copy to avoid sharing the pointer
		return &checkpoint.TokenUsage{
			InputTokens:         new.InputTokens,
			CacheCreationTokens: new.CacheCreationTokens,
			CacheReadTokens:     new.CacheReadTokens,
			OutputTokens:        new.OutputTokens,
			APICallCount:        new.APICallCount,
			SubagentTokens:      new.SubagentTokens,
		}
	}

	// Accumulate values
	existing.InputTokens += new.InputTokens
	existing.CacheCreationTokens += new.CacheCreationTokens
	existing.CacheReadTokens += new.CacheReadTokens
	existing.OutputTokens += new.OutputTokens
	existing.APICallCount += new.APICallCount

	// Accumulate subagent tokens if present
	if new.SubagentTokens != nil {
		existing.SubagentTokens = accumulateTokenUsage(existing.SubagentTokens, new.SubagentTokens)
	}

	return existing
}

